#!/bin/bash
# Delete Verilator precompiled headers in idle clones (regenerated by any rebuild).
set -eu
S=<scratch>
for c in "$S"/clones/*/; do
  n=$(basename "$c")
  if [[ $n == r4-meas-68c97849-* || $n == r4-meas-41d2bc2b-* || $n == r4-meas-b5802de9-8x8-1if || $n == r5-s9d ]]; then
    continue
  fi
  find "$c" -name '*.gch' -type f -delete
done
du -sh "$S"
